import AxeBuilder from '@axe-core/playwright';
import { expect, type Browser, type BrowserContext, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export type Role = 'viewer' | 'editor' | 'publisher' | 'admin';

const USERS = join(import.meta.dirname, '../../deployment/docker/.local/e2e/users.json');
export const GATEWAYS = (process.env.GATEWAY_URLS ?? 'http://localhost:8080,http://localhost:8081').split(',');
const CONSOLE_ORIGIN = new URL(process.env.CONSOLE_URL ?? 'http://localhost:8280').origin;

/** Passwords generated by the stack's init service (never committed). */
function password(role: Role): string {
  const all = JSON.parse(readFileSync(USERS, 'utf8')) as Record<Role, string>;
  return all[role];
}

export interface Session {
  context: BrowserContext;
  page: Page;
  /** CSP violations reported on console pages. */
  violations: () => Promise<string[]>;
}

declare global {
  interface Window {
    cspViolations?: string[];
  }
}

/** A fresh browser session signed in through Keycloak (authorization code + PKCE). */
export async function signIn(browser: Browser, role: Role): Promise<Session> {
  const context = await browser.newContext();
  const consoleErrors: string[] = [];
  await context.addInitScript(() => {
    window.cspViolations = [];
    document.addEventListener('securitypolicyviolation', (e) => {
      window.cspViolations?.push(`${e.documentURI} ${e.effectiveDirective} ${e.blockedURI}`);
    });
  });
  const page = await context.newPage();
  page.on('console', (m) => {
    if (m.type() === 'error' && /Content Security Policy|Trusted Type/i.test(m.text())
      && page.url().startsWith(CONSOLE_ORIGIN)) {
      consoleErrors.push(m.text());
    }
  });
  await page.goto('/');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await page.waitForURL(/\/realms\/gateway\/protocol\/openid-connect\/auth/);
  await page.locator('#username').fill(role);
  await page.locator('#password').fill(password(role));
  await page.locator('#kc-login').click();
  await page.waitForURL(`${CONSOLE_ORIGIN}/**`);
  await expect(page.locator('.who .badge')).toHaveText(role);
  const violations = async () => {
    const fromPage = page.url().startsWith(CONSOLE_ORIGIN)
      ? await page.evaluate(() => window.cspViolations ?? []) : [];
    return [...fromPage.filter((v) => v.startsWith(CONSOLE_ORIGIN)), ...consoleErrors];
  };
  return { context, page, violations };
}

/** WCAG 2.2 A/AA checks on the current page (axe-core). */
export async function expectAccessible(page: Page, what: string) {
  const r = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']).analyze();
  expect(r.violations.map((v) => `${v.id}: ${v.help} (${v.nodes.map((n) => n.target.join(' ')).join(', ')})`),
    `axe on ${what}`).toEqual([]);
}

/** Waits until every gateway answers `path` with `status`; returns the elapsed milliseconds. */
export async function untilGateways(path: string, status: number, headers: Record<string, string> = {},
  timeoutMs = 10_000): Promise<number> {
  const t0 = Date.now();
  const pending = new Set(GATEWAYS);
  while (pending.size > 0) {
    for (const g of [...pending]) {
      try {
        const r = await fetch(g + path, { headers });
        if (r.status === status) {
          pending.delete(g);
        }
      } catch {
        // gateway restarting: retry
      }
    }
    if (pending.size === 0) {
      break;
    }
    if (Date.now() - t0 > timeoutMs) {
      throw new Error(`${[...pending].join(', ')} did not answer ${path} with ${status} within ${timeoutMs} ms`);
    }
    await new Promise((r) => setTimeout(r, 50));
  }
  return Date.now() - t0;
}

export async function newChangeSet(page: Page, title: string): Promise<string> {
  await page.getByRole('button', { name: 'New change set' }).first().click();
  const dialog = page.getByRole('dialog', { name: 'New change set' });
  await dialog.getByLabel('Title').fill(title);
  await dialog.getByRole('button', { name: 'Create' }).click();
  await page.waitForURL(/\/changesets\/[^/]+$/);
  return new URL(page.url()).pathname.split('/').pop() ?? '';
}
